'use strict';
// Execute the actual, typechecked TypeScript exports; no classifier model.
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const ts = require('typescript');
const root = path.resolve(__dirname, '../..');
const sha = data => crypto.createHash('sha256').update(data).digest('hex');
const sourcePath = path.join(root, 'src/utils/ai_usage_classification.ts');
const source = fs.readFileSync(sourcePath, 'utf8');
const pins = {source:'00fcd076d0f3460ecea46588904242252a32b9500e43217c67a1a07e1cbe4b36', package:'cc4939f6416a91d4bfaa5bcdd3d448d2f74103a88bb269e0a8e393615cf32cef', lock:'abdf5aa71a8272423ebb9358d7aaa87edd7e65f6605c325fe231a4bcef70eeb7', typescript:'3ae902c92cc44dace175c0e69e13a4b0899f6983c6121d76b9ab8dd5795e7675', typescriptPackage:'822ef7ca6452205657b6288b066481ecf508bfbf43455d715cf7d3ec457561e6'};
const hashes = {source:sha(source), package:sha(fs.readFileSync(path.join(root,'package.json'))), lock:sha(fs.readFileSync(path.join(root,'package-lock.json'))), typescript:sha(fs.readFileSync(require.resolve('typescript'))), typescriptPackage:sha(fs.readFileSync(require.resolve('typescript/package.json'))), node:sha(fs.readFileSync(process.execPath)), oracle:sha(fs.readFileSync(__filename))};
for (const [key,pin] of Object.entries(pins)) assert.equal(hashes[key],pin,key);
assert.equal(process.version,'v24.22.1');
assert.equal(process.versions.v8,'13.6.233.17-node.58');
assert.equal(ts.version,'5.9.3');
const ast = ts.createSourceFile(sourcePath,source,ts.ScriptTarget.ES2022,true);
assert.deepEqual(ast.parseDiagnostics,[]);
assert.equal(ast.statements.length,2);
const exportNodes = ast.statements.filter(s => s.modifiers?.some(m => m.kind === ts.SyntaxKind.ExportKeyword));
assert.equal(exportNodes.length,2);
assert(ts.isVariableStatement(exportNodes[0]));
assert.equal(exportNodes[0].declarationList.declarations[0].name.text,'ADJUSTMENT_TYPES');
assert(ts.isFunctionDeclaration(exportNodes[1]));
assert.equal(exportNodes[1].name.text,'classifyAdjustment');
const extraction = exportNodes.map(s=>s.getText(ast)).join('\n');
const virtualFile = path.join(root,'__ai_classification_oracle__.ts');
const options = {target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.CommonJS,strict:true,noEmit:true,skipLibCheck:true,types:[],lib:['lib.es2022.d.ts']};
const host = ts.createCompilerHost(options), read = host.readFile.bind(host), exists = host.fileExists.bind(host);
host.readFile = f => f === virtualFile ? extraction : read(f);
host.fileExists = f => f === virtualFile || exists(f);
const program = ts.createProgram([virtualFile],options,host);
assert.deepEqual(ts.getPreEmitDiagnostics(program).map(d=>ts.flattenDiagnosticMessageText(d.messageText,'\n')),[]);
const sf = program.getSourceFile(virtualFile), checker = program.getTypeChecker();
const fn = sf.statements.find(ts.isFunctionDeclaration);
const signature = checker.signatureToString(checker.getSignatureFromDeclaration(fn),undefined,ts.TypeFormatFlags.NoTruncation);
const tuple = checker.typeToString(checker.getTypeAtLocation(sf.statements[0].declarationList.declarations[0].name),undefined,ts.TypeFormatFlags.NoTruncation);
assert.match(signature,/entryKind\?: unknown/); assert.match(signature,/string \| null/);
assert.match(tuple,/manual_grant/); assert.match(tuple,/other/);
const compiled = ts.transpileModule(extraction,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.CommonJS},reportDiagnostics:true});
assert.deepEqual(compiled.diagnostics,[]);
const context = {exports:{}}; vm.runInNewContext(compiled.outputText,context);
const classify = context.exports.classifyAdjustment;
const types = Array.from(context.exports.ADJUSTMENT_TYPES);
assert.deepEqual(types,['manual_grant','monthly_reset','subscription_credits','purchased_pack','gifted_credits','native_grant','refund','correction','activation','other']);
const raws = [];
function add(id,raw) { raws.push({id,raw}); }
add('empty','{}'); add('null-input','null'); add('wrong-kind','{"entryKind":"usage","source":{"toString":null}}');
for (const type of types) add('explicit-'+type,JSON.stringify({entryKind:'adjustment',adjustmentType:type,source:{toString:null},operation:{toString:null}}));
const sources = ['polar_meter_credit','free_credit_reset','free_credit_reset_worker','admin_credit_grant','credit_pack_purchase','activation','unknown'];
const operations = ['monthly_reset','purchase_pack','refund','correction','unknown'];
for (const source of sources) for (const operation of operations) for (const reason of ['Free benefits','other']) add(`collision-${source}-${operation}-${reason}`,JSON.stringify({entryKind:'adjustment',source,operation,reason}));
for (const [id,fragment] of Object.entries({missing:'',nulls:',"source":null,"operation":null,"reason":null',false:',"source":false,"operation":false',zero:',"source":0,"operation":-0',numbers:',"source":1e400,"operation":-1e400',unicode:',"source":"activa\\u0074ion","reason":"Free benefits\\ud800"',surrogate:',"source":"\\ud800","operation":"\\udfff","reason":"Free benefits"',array:',"source":[["activation"]]',nestedNull:',"source":[null,["activation"]]',object:',"source":{}',sourceError:',"source":{"toString":null},"operation":"refund"',operationError:',"source":"polar_meter_credit","operation":{"toString":null}',nestedError:',"source":[[{"toString":false}]]',duplicate:',"source":"activation","source":"admin_credit_grant"',duplicateKind:',"entryKind":"usage","entryKind":"adjustment","source":"activation"',reasonArray:',"source":"other","reason":["Free benefits"]',explicitArray:',"adjustmentType":["refund"],"operation":"correction"'})) add(id,'{"entryKind":"adjustment"'+fragment+'}');
const cases = raws.map(({id,raw})=>{ let result; try { result={value:classify(JSON.parse(raw))}; } catch (error) { result={error:error.name}; } return {id,raw,result}; });
const nativeFiles = ['src/utils/ai_usage.rs','src/utils/tts/settings.rs','src/utils/lossless_json.rs','src/utils/js_string.rs','src/utils/json_number.rs','tests/ai_usage_classification.rs'];
const nativeHashes = Object.fromEntries(nativeFiles.map(file=>[file,sha(fs.readFileSync(path.join(root,file)))]));
const output = JSON.stringify({metadata:{schema:1,node:process.version,v8:process.versions.v8,typescript:ts.version,hashes,nativeHashes,signature,tuple,exports:['ADJUSTMENT_TYPES','classifyAdjustment'],total:cases.length},cases},null,2)+'\n';
const [mode,dir,...extra] = process.argv.slice(2);
assert(['--write','--check'].includes(mode) && dir && !extra.length,'usage: --write DIR | --check DIR');
const real = fs.realpathSync(dir), repo = fs.realpathSync(root);
assert(real !== repo && !real.startsWith(repo+path.sep),'directory must be external');
const file = path.join(real,'ai_usage_classification_reference.json');
if (mode === '--write') { assert.equal(fs.readdirSync(real).length,0,'write requires an empty directory'); fs.writeFileSync(file,output,{flag:'wx'}); }
else { assert.deepEqual(fs.readdirSync(real),[path.basename(file)],'exact fixture directory'); assert.equal(fs.readFileSync(file,'utf8'),output,'fixture drift'); }
